export interface RecordUrgeInput {
  id: string;
  occurredAt: Instant;
  intensity: number;
  trigger?: string | null;
  durationMinutes?: number | null;
  copingActions?: readonly string[];
  outcome: UrgeOutcome;
  note?: string | null;
  now: Instant;
}

export type RecordUrgeError =
  InstantError | TextError | "invalid_intensity" | "invalid_duration" | "duplicate_id";

/**
 * Logs an urge. An urge with outcome "acted" does not close the period by itself: the UI
 * offers the relapse flow so that the user stays in control of what is recorded.
 */
export function recordUrge(
  journey: Journey,
  input: RecordUrgeInput,
): Result<Journey, RecordUrgeError> {
  if (journey.urges.some((u) => u.id === input.id)) return err("duplicate_id");
  const instantError = checkInstant(input.occurredAt, input.now);
  if (instantError) return err(instantError);
  if (
    !Number.isInteger(input.intensity) ||
    input.intensity < MIN_INTENSITY ||
    input.intensity > MAX_INTENSITY
  ) {
    return err("invalid_intensity");
  }
  const duration = input.durationMinutes ?? null;
  if (
    duration !== null &&
    (!Number.isInteger(duration) || duration < 0 || duration > MAX_URGE_DURATION_MINUTES)
  ) {
    return err("invalid_duration");
  }
  const trigger = input.trigger ?? null;
  const copingActions = input.copingActions ?? [];
  const tagError = checkTags(trigger === null ? copingActions : [trigger, ...copingActions]);
  if (tagError) return err(tagError);
  const note = normalizeNote(input.note);
  if (!note.ok) return note;

  const urge: UrgeEvent = {
    id: input.id,
    occurredAt: input.occurredAt,
    recordedAt: input.now,
    intensity: input.intensity,
    trigger,
    durationMinutes: duration,
    copingActions,
    outcome: input.outcome,
    note: note.value,
  };
  return ok({ ...journey, urges: [...journey.urges, urge] });
}

